param([string]$BaseUrl='http://127.0.0.1:8080',[int]$Requests=100)
$ErrorActionPreference='Stop';$root=Resolve-Path(Join-Path $PSScriptRoot '..\..');Set-Location $root
$cfg=@{};Get-Content .env|Where-Object{$_-match'^\s*([^#=\s]+)=(.*)$'}|ForEach-Object{$cfg[$matches[1]]=$matches[2].Trim().Trim('"').Trim("'")};$tenant=$cfg.PLATFORM_BOOTSTRAP_TENANT_ID
$token=(Invoke-RestMethod -Method Post "$BaseUrl/api/v1/auth/token" -ContentType application/json -Body(@{username=$cfg.PLATFORM_BOOTSTRAP_USER;password=$cfg.PLATFORM_BOOTSTRAP_PASSWORD}|ConvertTo-Json -Compress)).access_token;$h=@{Authorization="Bearer $token"};$endpoint=[Guid]::NewGuid();$values=@()
for($i=0;$i-lt$Requests;$i++){$id=[Guid]::NewGuid();$body=@{event=@{eventId=$id;tenantId=$tenant;domain='Process';eventTime=[DateTimeOffset]::UtcNow.ToString('o');endpointId=$endpoint;processEntityId="sprint32-perf-$i";entityId="sprint32-perf-$i";fields=@{path='C:\Windows\System32\notepad.exe';commandLine='notepad.exe';processName='notepad.exe';endpointId=$endpoint.ToString()};evidenceReference="controlled://sprint32/performance/$id";late=$false;incomplete=$false;missingFields=@();quality=@('complete')};productionFindings=$false;mode='DryRun'}|ConvertTo-Json -Depth 10 -Compress;$w=[Diagnostics.Stopwatch]::StartNew();Invoke-RestMethod -Method Post "$BaseUrl/internal/v1/detection-events:evaluate" -Headers $h -ContentType application/json -Body $body|Out-Null;$w.Stop();$values+=$w.Elapsed.TotalMilliseconds}
$sorted=$values|Sort-Object;$p50=$sorted[[math]::Floor(($sorted.Count-1)*.50)];$p95=$sorted[[math]::Floor(($sorted.Count-1)*.95)];$report=[ordered]@{schemaVersion='sprint32-detection-performance.v1';executedAt=[DateTimeOffset]::UtcNow.ToString('o');requests=$Requests;activeRules=39;mode='DryRun';productionFindings=$false;p50Milliseconds=[math]::Round($p50,2);p95Milliseconds=[math]::Round($p95,2);maximumMilliseconds=[math]::Round(($sorted|Measure-Object -Maximum).Maximum,2);passed=$p95-lt250};$report|ConvertTo-Json|Set-Content artifacts/sprint32-detection-performance.json -Encoding utf8;$report|ConvertTo-Json;if(-not$report.passed){throw 'Sprint 32 detection p95 exceeded 250 ms.'}
